//! Actual immutable original registration and real original value fixpoint/Walker.
use crate::lint::Registry;
#[path="../fixtures/original_policies/stored_refs_workspace.rs"]mod original;
#[path="../fixtures/native-stored-refs-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
#[test]fn original_stored_refs_whole_reports_cover_real_declarations_lists_relations_allow_and_maps(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/stored_refs_workspace.rs"))),"ed4beb748aa38ee45ff5b947b40abaf680509a65");for case in fixture::CASES{let root=scratch::dir(&format!("old-stored_refs-{case}"));for(relative,bytes)in fixture::files(case){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,crate::run::Options{root:root.clone(),lints:vec!["stored_refs".into()],no_cache:true,raw:true,..Default::default()}).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"actual original parsing failed for {case}: {:?}",sem.errors);if *case=="noncode"{let mut map_body=false;for ty in sem.objtree.iter_types(){for(_,proc_type)in ty.get().procs.iter(){for body in proc_type.value.iter(){if body.code.is_some()&&sem.file_of(body.location)==Some("maps/stored.dm"){map_body=true}}}}assert!(map_body,"actual original loader must compile the map body before policy selection is tested");}let outcome=old.run_one(old.reg.lints[0].as_ref());assert!(outcome.internal_error.is_none());if matches!(*case,"exempt"|"raw_relations"){assert!(outcome.run.sites.is_empty());}else{assert!(!outcome.run.sites.is_empty(),"genuine positive {case}");}if *case=="noncode"{assert!(outcome.run.sites.iter().any(|s|s.rel=="code/types.dm"&&s.msg.contains("maps/stored.dm:2")),"map assignments contribute to actual old code declaration");assert!(!outcome.run.sites.iter().any(|s|s.rel.starts_with("maps/")),"old reports code declarations only");}assert!(outcome.run.notes.is_empty());if *case=="allow"{assert_eq!(outcome.allow_used.len(),1);}else{assert!(outcome.allow_used.is_empty());}println!("ORIGINAL_STORED_REFS_FULL={}",serde_json::json!({"case":case,"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text}));}}
